use std::any::TypeId;
use std::fmt;

use crate::{Error, Key, RawId, Ref, Result};

/// What deleting a referenced row does to the rows that refer to it.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum OnDelete {
    /// Refuse the delete while a row that will survive it still refers to it.
    Restrict,
    /// Delete the referring rows too.
    Cascade,
    /// Set the referring rows' column to `None`. Only for `Option` columns.
    SetNull,
}

/// A foreign key column of `T`. Generated by `#[derive(Relation)]`.
pub struct Reference<T: Row> {
    pub column: &'static str,
    pub references: &'static str,
    pub parent: fn() -> TypeId,
    pub on_delete: OnDelete,
    /// Call the closure with each row whose column refers to the given parent, using the column's index.
    pub children: fn(&T::Indexes, RawId, &mut dyn FnMut(RawId)),
    /// Set the column to `None`, for `on_delete = set_null`.
    pub set_null: Option<fn(&mut T)>,
}

/// A row type. Implemented by `#[derive(Relation)]`, not by hand.
pub trait Row: Sized + 'static {
    /// The id type, [`crate::Id<Self>`] unless `#[relation(key = ...)]` says otherwise.
    type Key: Key;
    type Indexes: Default;
    /// The row with its indexed and foreign key columns behind shared references
    /// and every other column behind mutable ones. Generated as `{Name}Mut`.
    type Mut<'a>;

    const NAME: &'static str;
    const REFERENCES: &'static [Reference<Self>];

    fn project(&mut self) -> Self::Mut<'_>;

    fn check_unique(&self, indexes: &Self::Indexes) -> Result<()>;
    fn index_insert(&self, indexes: &mut Self::Indexes, id: Self::Key);
    fn index_remove(&self, indexes: &mut Self::Indexes, id: Self::Key);
}

/// A row with no unique index and no foreign key, so inserting it can't fail.
/// Implemented by `#[derive(Relation)]` for such rows.
#[diagnostic::on_unimplemented(
    message = "inserting `{Self}` can fail",
    label = "`{Self}` has a unique index or a foreign key",
    note = "insert it through the database: `Database::insert` checks constraints and returns a `Result`"
)]
pub trait Unconstrained: Row {}

struct Slot<T> {
    generation: u32,
    row: Option<T>,
}

/// A set of rows of `T` and their indexes.
///
/// Rows are handed out as `&T`, or as `T::Mut` with the indexed columns read-only.
/// Writes to indexed columns go through the [`crate::Database`], which keeps
/// indexes and foreign keys consistent.
pub struct Relation<T: Row> {
    slots: Vec<Slot<T>>,
    free: Vec<u32>,
    len: usize,
    indexes: T::Indexes,
}

impl<T: Row> Default for Relation<T> {
    fn default() -> Self {
        Self { slots: Vec::new(), free: Vec::new(), len: 0, indexes: Default::default() }
    }
}

impl<T: Row + fmt::Debug> fmt::Debug for Relation<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_map().entries(self.iter().map(|r| (r.id(), r.row()))).finish()
    }
}

impl<T: Row> Relation<T> {
    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn contains(&self, id: T::Key) -> bool {
        self.get(id).is_some()
    }

    pub fn get(&self, id: T::Key) -> Option<&T> {
        let raw = id.raw();
        let slot = self.slots.get(raw.index as usize)?;
        if slot.generation != raw.generation {
            return None;
        }
        slot.row.as_ref()
    }

    /// Mutable access to a row's unindexed columns. Indexed and foreign key columns
    /// are read-only here; change them with [`crate::Database::set`].
    pub fn get_mut(&mut self, id: T::Key) -> Option<T::Mut<'_>> {
        let slot = self.slot_mut(id)?;
        Some(slot.row.as_mut().expect("live slot has a row").project())
    }

    pub fn get_ref(&self, id: T::Key) -> Option<Ref<'_, T>> {
        self.get(id).map(|row| Ref::new(id, row))
    }

    pub fn iter(&self) -> impl Iterator<Item = Ref<'_, T>> {
        self.slots.iter().enumerate().filter_map(|(index, slot)| {
            let row = slot.row.as_ref()?;
            let raw = RawId { index: index as u32, generation: slot.generation };
            Some(Ref::new(T::Key::from_raw(raw), row))
        })
    }

    pub fn iter_mut(&mut self) -> impl Iterator<Item = (T::Key, T::Mut<'_>)> {
        self.slots.iter_mut().enumerate().filter_map(|(index, slot)| {
            let row = slot.row.as_mut()?;
            let raw = RawId { index: index as u32, generation: slot.generation };
            Some((T::Key::from_raw(raw), row.project()))
        })
    }

    pub fn ids(&self) -> impl Iterator<Item = T::Key> + '_ {
        self.iter().map(|r| r.id())
    }

    #[doc(hidden)]
    pub fn indexes(&self) -> &T::Indexes {
        &self.indexes
    }

    /// Look up an id that an index returned, so it must be live.
    #[doc(hidden)]
    pub fn indexed(&self, id: T::Key) -> Ref<'_, T> {
        self.get_ref(id).expect("index refers to a live row")
    }

    /// Take a slot for a row that is about to be built, so the row can know its own id.
    pub(crate) fn reserve(&mut self) -> T::Key {
        let raw = match self.free.pop() {
            Some(index) => {
                let slot = &self.slots[index as usize];
                debug_assert!(slot.row.is_none());
                RawId { index, generation: slot.generation }
            }
            None => {
                let index = u32::try_from(self.slots.len()).expect("fewer than 2^32 slots");
                self.slots.push(Slot { generation: 0, row: None });
                RawId { index, generation: 0 }
            }
        };
        T::Key::from_raw(raw)
    }

    /// Give back a reserved slot whose row was refused. The id may have escaped
    /// into the refused row, so the generation moves on.
    pub(crate) fn release(&mut self, id: T::Key) {
        let slot = &mut self.slots[id.raw().index as usize];
        debug_assert!(slot.row.is_none() && slot.generation == id.raw().generation);
        slot.generation = slot.generation.wrapping_add(1);
        self.free.push(id.raw().index);
    }

    /// Fill a reserved slot. On a unique violation the slot is released.
    pub(crate) fn fill(&mut self, id: T::Key, row: T) -> Result<()> {
        if let Err(err) = row.check_unique(&self.indexes) {
            self.release(id);
            return Err(err);
        }
        row.index_insert(&mut self.indexes, id);
        self.slots[id.raw().index as usize].row = Some(row);
        self.len += 1;
        Ok(())
    }

    /// Replace a live row. On a unique violation the old row stays.
    pub(crate) fn replace(&mut self, id: T::Key, row: T) -> Result<()> {
        let slot = self.slot_mut(id).expect("replaced row is live");
        let old = slot.row.take().expect("live slot has a row");

        old.index_remove(&mut self.indexes, id);
        if let Err(err) = row.check_unique(&self.indexes) {
            old.index_insert(&mut self.indexes, id);
            self.slots[id.raw().index as usize].row = Some(old);
            return Err(err);
        }

        row.index_insert(&mut self.indexes, id);
        self.slots[id.raw().index as usize].row = Some(row);
        Ok(())
    }

    /// Change one column in place, keeping the indexes in step. Returns the old value.
    /// The caller checks foreign keys and puts the old value back if they fail.
    pub(crate) fn set<K>(
        &mut self,
        id: T::Key,
        get_mut: fn(&mut T) -> &mut K,
        value: K,
    ) -> Result<K> {
        let Self { slots, indexes, .. } = self;
        let raw = id.raw();
        let row = slots
            .get_mut(raw.index as usize)
            .filter(|slot| slot.generation == raw.generation)
            .and_then(|slot| slot.row.as_mut())
            .ok_or(Error::NotFound { relation: T::NAME })?;

        row.index_remove(indexes, id);
        let old = std::mem::replace(get_mut(row), value);
        if let Err(err) = row.check_unique(indexes) {
            *get_mut(row) = old;
            row.index_insert(indexes, id);
            return Err(err);
        }
        row.index_insert(indexes, id);
        Ok(old)
    }

    /// Change a row in place without checking unique indexes, keeping the indexes in step.
    /// Only for changes that can't break a unique index.
    pub(crate) fn modify_unchecked(&mut self, id: T::Key, f: fn(&mut T)) {
        let Self { slots, indexes, .. } = self;
        let raw = id.raw();
        let row = slots
            .get_mut(raw.index as usize)
            .filter(|slot| slot.generation == raw.generation)
            .and_then(|slot| slot.row.as_mut())
            .expect("modified row is live");
        row.index_remove(indexes, id);
        f(row);
        row.index_insert(indexes, id);
    }

    /// Remove a live row.
    pub(crate) fn remove(&mut self, id: T::Key) {
        let slot = self.slot_mut(id).expect("removed row is live");
        let row = slot.row.take().expect("live slot has a row");
        slot.generation = slot.generation.wrapping_add(1);
        row.index_remove(&mut self.indexes, id);
        self.free.push(id.raw().index);
        self.len -= 1;
    }

    fn slot_mut(&mut self, id: T::Key) -> Option<&mut Slot<T>> {
        let raw = id.raw();
        let slot = self.slots.get_mut(raw.index as usize)?;
        (slot.generation == raw.generation && slot.row.is_some()).then_some(slot)
    }
}

/// Rows without constraints can't break one, so they are inserted without a database
/// and without a `Result`.
impl<T: Unconstrained> Relation<T> {
    pub fn insert(&mut self, row: T) -> T::Key {
        self.insert_with(|_| row)
    }

    /// Insert a row built from its own id.
    pub fn insert_with(&mut self, f: impl FnOnce(T::Key) -> T) -> T::Key {
        let id = self.reserve();
        let row = f(id);
        self.fill(id, row).expect("a row without unique indexes can't break one");
        id
    }
}

impl<T: Row> std::ops::Index<T::Key> for Relation<T> {
    type Output = T;

    fn index(&self, id: T::Key) -> &T {
        self.get(id).unwrap_or_else(|| panic!("no such {}: {id:?}", T::NAME))
    }
}
